#include <stdio.h>

void pick_larger(int **result, int *a, int *b) {
    *result = (*a >= *b) ? a : b;
}

int main() {
    int x = 12, y = 30;
    int *larger = NULL;
    pick_larger(&larger, &x, &y);
    printf("larger = %d\n", *larger);
    *larger = 0;
    printf("x=%d y=%d\n", x, y);
    return 0;
}
